// Reviewed against the pinned canonical converted rules. These are decisions,
// not extraction patterns. The private audit attaches each rule's SHA-256.
const damage = (formula, type) => ({ formula, type });
const save = (ability, onSave, bonus = '') => ({ ability, onSave, bonus });
const phase = (name, rolls = [], savingThrow, activation, attack) => ({ name, rolls, savingThrow, activation, attack });
const plain = rationale => ({ category: 'no-damage-no-save', rationale });
const manual = (category, rationale) => ({ category, rationale });
const cast = (rolls, savingThrow, rationale, followups = []) =>
  ({ category: savingThrow ? 'cast-damage-and-save' : 'cast-damage', rolls, savingThrow, rationale, followups });
const prompt = (savingThrow, rationale, followups = []) =>
  ({ category: 'save-only', savingThrow, rationale, followups });
const gated = (category, rationale, followups, attack) => ({ category, rationale, followups, attack });
const con = onSave => save('con', onSave);
const dex = onSave => save('dex', onSave);
const wis = onSave => save('wis', onSave);
const half = 'Half damage.';
const none = 'No damage.';
const unaffected = 'Unaffected.';

const force = formula => damage(formula, 'force');
const fire = formula => damage(formula, 'fire');
const acid = formula => damage(formula, 'acid');
const physical = formula => damage(formula, 'bludgeoning');
const necrotic = formula => damage(formula, 'necrotic');
const radiant = formula => damage(formula, 'radiant');
const psychic = formula => damage(formula, 'psychic');
const cold = formula => damage(formula, 'cold');
const piercing = formula => damage(formula, 'piercing');
const lightning = formula => damage(formula, 'lightning');

